                box(0.05, 0.3, 0.055, bladeMat, 0, 0.28);
                box(0.09, 0.22, 0.095, mat, 0, 0.1);            // 리시버
                { const magz = box(0.05, 0.2, 0.07, dark, 0, -0.06, 0.02); magz.rotation.x = -0.12; }  // 탄창
                box(0.05, 0.11, 0.07, wood, 0, -0.02, -0.03);   // 그립
