                    into(fl, () => sp(0.055, s * 0.035, 0, 0, SKIN, 1.35, 0.55, 1.05));  // 노 젓는 물갈퀴(납작한 판)
                    jt(fl, 'z', 0.5 * s, ph[i++], { gain: 1.8 });        // 지느러미발 노 젓기
