                    sp(P.hr * 0.56, 0, P.hr * 0.62, P.hr * 0.92, CREAM, 1.25, 0.85, 0.8);        // 주둥이
                    sp(P.hr * 0.2, 0, P.hr * 0.74, P.hr * 1.26, GM(saber ? 0x4e3b30 : 0xe08e94)); // 코
