            const bodyMat = PANTHER ? M(0x4a3d70) : BROWN ? M(0xd0521c) : mat;   // 갈색말: 밤색도 올리브로 죽어 쨍한 레드-체스트넛으로
            const legMat = PANTHER ? M(0x281f42) : BROWN ? M(0x9a3a12) : dark;
